        A = [row[:] for row in M]
        lead = 0
        for r in range(n):
            if lead >= n:
                break
            i = r
            while A[i][lead] == 0:
                i += 1
                if i == n:
                    i = r
                    lead += 1
                    if lead == n:
                        return A, False
            A[r], A[i] = A[i], A[r]
            for i in range(r + 1, n):
                factor = Fraction(A[i][lead], A[r][lead])
                for j in range(lead, n):
                    A[i][j] -= factor * A[r][j]
        return A, True

    def rank_variance(M):
        A, success = gaussian_elimination(M)
